/*
 * A355720  Expansion of e.g.f. exp( x/(2 - exp(x)) ).
 * https://oeis.org/A355720
 *
 * Offset:    0    (a(0) is the first term)
 * Keywords:  nonn
 * Formula:   not stated
 * Range:     u8 n <= 4, u16 n <= 6, u32 n <= 10, u64 n <= 17, u128 n <= 19,
 *            big any n
 * Helpers:   binomial
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/*
 * OEIS A355720: a(n) = sum_{k=1..n} A052882(k) * binomial(n-1, k-1) * a(n-k)
 * with a(0) = 1.
 * A052882(k) = k! * [x^k] (x/(2 - exp(x))) (integer coefficients).
 *
 * The sequence is generated by first computing the integer coefficients
 * B[k] = k! * coefficient of x^k in x/(2 - exp(x)), which satisfy
 *          B_0 = 0
 *          B_n = δ_{n,1}·n! + sum_{i=1..n} B_{n-i} * binomial(n, i)
 * (δ_{n,1} is 1 for n=1, 0 otherwise).
 *
 * Then it is used in the recurrence above to compute a(n).
 *
 * The implementation uses static caching so that calls with arbitrary
 * n order are efficient.  All computations use the seq_t type (unsigned
 * integer, possibly arbitrary‑precision) and do not rely on floating
 * point arithmetic.
 */

#include <stdlib.h>
#include <stddef.h>
#include "../utils/binomial.h"

/* External linkages defined by the build */
extern seq_t binomial(idx_t n, idx_t k);

/* Cached arrays for B[n] (A052882(n)) and a[n] */
static seq_t *B = NULL;            /* B[0] = 0, B[1..] = k! * coeff */
static seq_t *Aarr = NULL;         /* a[0] = 1, a[1..] = sequence terms */
static size_t cache_size = 0;      /* number of computed elements */

seq_t a(idx_t n)
{
    /* Ensure caching arrays are large enough */
    if ((size_t)n + 1 > cache_size) {
        size_t new_size = (size_t)n + 1;
        if (cache_size == 0) {
            B    = (seq_t *)malloc(new_size * sizeof(seq_t));
            Aarr = (seq_t *)malloc(new_size * sizeof(seq_t));
        } else {
            B    = (seq_t *)realloc(B,    new_size * sizeof(seq_t));
            Aarr = (seq_t *)realloc(Aarr, new_size * sizeof(seq_t));
        }

        /* Initialize B[0] = 0;  Aarr[0] = 1 for the very first allocation */
        if (cache_size == 0) {
            B[0]    = 0;
            Aarr[0] = 1;
        }

        /* Compute B from previous cache_size up to n */
        for (idx_t i = cache_size; i <= n; ++i) {
            seq_t sum = 0;
            for (idx_t j = 1; j <= i; ++j) {
                /* B_i uses B_{i-j} * binomial(i, j) */
                sum += B[i - j] * binomial((idx_t)i, (idx_t)j);
            }
            if (i == 1) sum += (seq_t)1;    /* δ_{i,1}·i! = 1 */
            B[i] = sum;
        }

        /* Compute a from previous cache_size up to n */
        for (idx_t i = (cache_size == 0 ? 1 : cache_size); i <= n; ++i) {
            seq_t sum = 0;
            for (idx_t k = 1; k <= i; ++k) {
                /* a_i uses B_k * binomial(i-1, k-1) * a_{i-k} */
                sum += B[k] * binomial((idx_t)(i - 1), (idx_t)(k - 1)) * Aarr[i - k];
            }
            Aarr[i] = sum;
        }

        cache_size = new_size;
    }
    return Aarr[(size_t)n];
}
